                if allow_legacy and os.getenv(f"{agent_provider.upper()}_MODEL_MAP_JSON") is None
                else f"{agent_provider.upper()}_MODEL_MAP_JSON"
            )
            agent_model_map = _model_map(model_map_env, profile.capability_models)
